			return 25;
		}

		/* @Override */
		public Icon getValue(PluginDescription rowObject, Settings settings,
				List<PluginDescription> data, ServiceProvider sp)
    {
			return statusIconMap.get(rowObject.getStatus());
		}
	}

	/**
