	 */
	private class PluginCategoryColumn : AbstractDynamicTableColumn<PluginDescription, string, List<PluginDescription>> {

		/* @Override */
		public string getColumnName() {
			return "Category";
		}

		/* @Override */
		public int getColumnPreferredWidth() {
			return 200;
		}

